    'ab.p1': { ja:'✓ <strong>明朗な料金</strong> — 月¥4,990、追加課金・隠れた費用は一切なし', en:'✓ <strong>Clear pricing</strong> — ¥4,990/mo, no hidden fees', zh:'✓ <strong>明朗的价格</strong> — 月¥4,990,无追加扣款·隐藏费用', ko:'✓ <strong>명확한 요금</strong> — 월 ¥4,990, 추가 결제·숨겨진 비용 없음', vi:'✓ <strong>Giá rõ ràng</strong> — ¥4,990/tháng, không phí ẩn' },
    'ab.p2': { ja:'✓ <strong>解約自由</strong> — 違約金ゼロ、いつでも解約OK', en:'✓ <strong>Cancel anytime</strong> — zero penalty, cancel anytime', zh:'✓ <strong>自由取消</strong> — 违约金 0,随时可取消', ko:'✓ <strong>자유 해지</strong> — 위약금 제로, 언제든 해지 OK', vi:'✓ <strong>Hủy tự do</strong> — Không phí phạt, hủy bất cứ lúc nào' },
    'ab.p3': { ja:'✓ <strong>日本語サポート</strong> — 代表が直接対応', en:'✓ <strong>Japanese support</strong> — CEO handles directly', zh:'✓ <strong>日语支持</strong> — CEO 直接对应', ko:'✓ <strong>일본어 지원</strong> — 대표가 직접 대응', vi:'✓ <strong>Hỗ trợ tiếng Nhật</strong> — CEO trực tiếp xử lý' },
    'ab.p4': { ja:'✓ <strong>データオーナーシップ</strong> — 顧客データは顧客のもの。いつでもエクスポート可能', en:'✓ <strong>Data ownership</strong> — your data is yours. Export anytime', zh:'✓ <strong>数据所有权</strong> — 客户数据归客户。随时可导出', ko:'✓ <strong>데이터 소유권</strong> — 고객 데이터는 고객의 것. 언제든 내보내기 가능', vi:'✓ <strong>Sở hữu dữ liệu</strong> — Dữ liệu của bạn là của bạn. Xuất bất cứ lúc nào' },
    'ab.p5': { ja:'✓ <strong>セキュリティ重視</strong> — 国内サーバー・SSL常時暗号化・Stripe決済', en:'✓ <strong>Security first</strong> — domestic servers, always-on SSL, Stripe payments', zh:'✓ <strong>重视安全</strong> — 国内服务器·SSL 常时加密·Stripe 支付', ko:'✓ <strong>보안 중시</strong> — 국내 서버·SSL 상시 암호화·Stripe 결제', vi:'✓ <strong>An ninh là ưu tiên</strong> — Server trong nước, SSL luôn bật, Stripe' },
