    'ts.metric12': { ja:'スタッフ満足度: <strong>67% → 92%</strong>', en:'Staff satisfaction: <strong>67% → 92%</strong>', zh:'员工满意度: <strong>67% → 92%</strong>', ko:'직원 만족도: <strong>67% → 92%</strong>', vi:'Hài lòng NV: <strong>67% → 92%</strong>' },
    'ts.metric13': { ja:'多店舗管理時間: <strong>10h → 2h</strong>', en:'Multi-store mgmt: <strong>10h → 2h</strong>', zh:'多店管理: <strong>10h → 2h</strong>', ko:'다점포 관리: <strong>10h → 2h</strong>', vi:'QL nhiều CH: <strong>10h → 2h</strong>' },
