    'ftlaw.lead': { ja:'知らずに違反、はもう終わり', en:'No more unknowingly violating the law', zh:'不知不觉违反法律的时代结束了', ko:'모르고 위반하는 시대는 끝', vi:'Hết thời vô tình phạm luật' },
