    'cr.p1_name': { ja:'📨 メール応募', en:'📨 Email Application', zh:'📨 邮件应聘', ko:'📨 이메일 응모', vi:'📨 Nộp qua email' },
    'cr.p1_desc': { ja:'下記メールアドレスに、ご経歴・志望動機を簡単にお送りください。<br>履歴書フォーマット不問 (Word/PDF/Notion など何でも可)。GitHub URL / ポートフォリオがあると◎', en:'Send brief CV + motivation to the email below.<br>Any resume format OK (Word/PDF/Notion etc.). GitHub URL / portfolio is a plus.', zh:'向下方邮箱发送简历与动机简单介绍。<br>简历格式不限 (Word/PDF/Notion 等均可)。有 GitHub URL / 作品集更佳。', ko:'아래 이메일로 약력・지원동기 간단히 송신.<br>이력서 포맷 불문 (Word/PDF/Notion 등). GitHub URL / 포트폴리오 있으면◎', vi:'Gửi CV ngắn + động lực đến email dưới.<br>Mọi định dạng CV OK (Word/PDF/Notion). Có URL GitHub / portfolio là điểm cộng.' },
    'cr.p2_name': { ja:'💬 30分カジュアル面談 (オンライン)', en:'💬 30-min Casual Chat (Online)', zh:'💬 30 分钟休闲面试 (在线)', ko:'💬 30분 캐주얼 면담 (온라인)', vi:'💬 Trò chuyện 30 phút (Trực tuyến)' },
    'cr.p2_desc': { ja:'代表 小泉と1on1。お互いの価値観・働き方・期待値をすり合わせ。<br>選考というより「お互いを知る場」です。', en:'1-on-1 with CEO Koizumi. Align on values, work style, expectations.<br>More "getting to know each other" than selection.', zh:'与代表小泉 1 对 1。互相调整价值观・工作方式・期待值。<br>不是选拔而是「相互了解的场合」。', ko:'대표 코이즈미와 1on1. 서로 가치관・일하는 방식・기대치 조율.<br>선발이라기보다 「서로를 아는 자리」.', vi:'1-1 với CEO Koizumi. Cùng nhất quán giá trị, phong cách, kỳ vọng.<br>Hơn là "tìm hiểu nhau" hơn lựa chọn.' },
    'cr.p3_name': { ja:'🛠 トライアル業務 (任意・有償)', en:'🛠 Trial Work (Optional / Paid)', zh:'🛠 试用工作 (任意・有偿)', ko:'🛠 트라이얼 업무 (선택・유상)', vi:'🛠 Công việc thử (Tùy chọn / Trả phí)' },
    'cr.p3_desc': { ja:'エンジニアの場合、小さな機能を実装する2-4週間のトライアル業務 (有償・¥3,000/h)。<br>「合うか合わないか」を実際の業務で確かめます。', en:'For engineers, 2-4 week trial implementing a small feature (paid · ¥3,000/h).<br>Check "fit or not" through real work.', zh:'工程师情况下,实施小功能的 2-4 周试用 (有偿・¥3,000/h)。<br>通过实际业务确认「合不合」。', ko:'엔지니어의 경우 작은 기능 구현 2-4주 트라이얼 (유상・¥3,000/h).<br>「맞는지 안 맞는지」를 실제 업무로 확인.', vi:'Với kỹ sư, thử 2-4 tuần triển khai TN nhỏ (trả phí · ¥3,000/h).<br>Kiểm tra "hợp hay không" qua công việc thực.' },
    'cr.p4_name': { ja:'✅ 内定・契約', en:'✅ Offer / Contract', zh:'✅ 录用 / 合约', ko:'✅ 채용・계약', vi:'✅ Offer / Hợp đồng' },
    'cr.p4_desc': { ja:'条件提示。お互い納得したら正式契約。<br>原則1週間以内に判断、長引かせません。試用期間3ヶ月。', en:'Terms offered. On mutual agreement, formal contract.<br>Decision in principle within a week, no dragging. 3-month probation.', zh:'条件提示。互相同意后正式签约。<br>原则上 1 周内决定,不拖延。试用期 3 个月。', ko:'조건 제시. 서로 납득하면 정식 계약.<br>원칙 1주일 이내 판단, 늘리지 않음. 시용 기간 3개월.', vi:'Đưa điều khoản. Khi cả hai đồng ý, ký HĐ chính thức.<br>Quyết định nguyên tắc trong 1 tuần, không kéo dài. Thử việc 3 tháng.' },
    'cr.apply_h2': { ja:'一緒に作ってくれる仲間を、心から待っています', en:'We genuinely look forward to building with you', zh:'诚心期待与您一起创造的伙伴', ko:'함께 만들어 줄 동료를 진심으로 기다립니다', vi:'Thật lòng mong chờ đồng nghiệp cùng xây dựng' },
    'cr.apply_p': { ja:'「シフト管理ツール」と聞いて地味に感じるかもしれません。<br>でも、毎月3時間悩んでいたオーナーが10分で帰宅できる。<br>それは、人の人生を変える、立派な仕事です。', en:'"Shift management tool" might sound mundane.<br>But owners who agonized for 3 hours monthly can now leave in 10 minutes.<br>That\'s honorable work that changes lives.', zh:'听到「班次管理工具」可能觉得朴素。<br>但每月烦恼 3 小时的老板能在 10 分钟回家。<br>那是改变人生的高尚工作。', ko:'「시프트 관리 도구」 라 들으면 평범하게 느낄지도.<br>하지만 매월 3시간 고민하던 오너가 10분만에 귀가 가능.<br>그건 인생을 바꾸는 훌륭한 일.', vi:'"Công cụ quản lý ca" nghe có vẻ bình thường.<br>Nhưng chủ tiệm từng đau đầu 3h/tháng giờ về sau 10 phút.<br>Đó là công việc cao quý đổi đời.' },
    'cr.apply_btn': { ja:'📨 まずはメールで話を聞く', en:'📨 Start with a chat by email', zh:'📨 先用邮件聊聊', ko:'📨 먼저 이메일로 이야기', vi:'📨 Bắt đầu trò chuyện qua email' },
    'cr.apply_phone': { ja:'📞 080-5168-3303 / 代表 小泉 咲太', en:'📞 080-5168-3303 / CEO Shota Koizumi', zh:'📞 080-5168-3303 / 代表 小泉 咲太', ko:'📞 080-5168-3303 / 대표 코이즈미 쇼타', vi:'📞 080-5168-3303 / CEO Shota Koizumi' },
    'cr.f_brand': { ja:'RAKURAKU / 代表 小泉 咲太 · 神奈川県横浜市桜木町', en:'RAKURAKU / CEO Shota Koizumi · Sakuragicho, Yokohama, Kanagawa', zh:'RAKURAKU / 代表 小泉 咲太 · 神奈川县横滨市樱木町', ko:'RAKURAKU / 대표 코이즈미 쇼타 · 가나가와현 요코하마시 사쿠라기초', vi:'RAKURAKU / CEO Shota Koizumi · Sakuragicho, Yokohama, Kanagawa' },
    'cr.f_roadmap': { ja:'ヒアリング調査の声', en:'Interview Voices', zh:'访谈调查心声', ko:'인터뷰 조사 목소리', vi:'Tiếng nói phỏng vấn' },

